# The show_playlist API returns the songs in the playlist under the "songs" key.
# I will now proceed to:
# - For each playlist, get the songs.
# - Identify songs that are in the old_songs list.
# - Remove those songs from the playlist by recreating the playlist without those songs.
# - Add the removed songs to the "Archived Playlist Songs" playlist.
# 
# First, I will gather all songs to archive by playlist.
songs_to_remove_by_playlist = {}

for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    playlist_details = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if "songs" not in playlist_details:
        continue
    songs_in_playlist = playlist_details["songs"]
    to_remove = []
    for song in songs_in_playlist:
        if song["title"] in old_songs:
            to_remove.append(song)
    if to_remove:
        songs_to_remove_by_playlist[playlist_id] = {
            "playlist_title": playlist["title"],
            "songs_to_remove": to_remove,
            "songs_to_keep": [song for song in songs_in_playlist if song not in to_remove]
        }

print(songs_to_remove_by_playlist)  # To verify the songs to remove by playlist.

